window.MG_LAZY_DATA["data/lazy/resources/security-v26-002-ca2d186119bb4d1f.json"]={sha256:"ca2d186119bb4d1f6c85545d63fbf3922370f896b0e1e6cf989022a586a4493f",value:{"sources":[{"id":"v26-case-d6ec8bfdac3d757a","url":"https://content.govdelivery.com/accounts/USDHSCISA/bulletins/3543f28","title":"CISA releases updated Zero Trust Maturity Model","titleEn":"CISA releases updated Zero Trust Maturity Model","publisher":"CISA","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-002","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-002","related":[{"id":"security-v26-003","referenceUrls":["https://csrc.nist.gov/pubs/sp/800/63/4/final"],"title":"NIST 數位身分：IAL、AAL 與 FAL 的分離決策","titleEn":"NIST digital identity: separating IAL, AAL and FAL","why":"用兩課的可觀察驗收條件比較模型邊界：覆蓋率可從原始清單重算，沒有平均序位等級；每個未驗證項目都有負責人與截止日。 交付25項證據矩陣、五支柱差距說明與下一輪驗證排程。","whyEn":"Compare model boundaries using observable acceptance criteria: Coverage can be recomputed from raw rows without averaging ordinal levels; every unverified item has an owner and deadline. Deliver the 25-item evidence matrix, pillar-by-pillar gap analysis and next validation schedule.","difference":"以匿名閱覽、學徒成績、管理員操作三種服務建立資料與傷害情境；各自記錄 IAL、AAL、FAL 的理由，不把登入成功當真實身分已查證。","differenceEn":"Model data and harm for anonymous reading, learner grades and administration; justify IAL, AAL and FAL independently rather than treating successful login as proven real-world identity.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["證據覆蓋率=有完整且未過期證據的需求數/固定需求總數；成熟度等級是序位，不能直接平均成安全分數。 教學清單25項；17項有設定快照、負責人與最近一次測試，8項缺證據。 覆蓋17/25×100=68%；補齊4項後21/25×100=84%，仍有4項未驗證。","保證向量是三個分開的要求；本地符合率只計算自訂的驗收案例，不可宣稱它就是 NIST 認證分數。 為自訂服務剖面列16個驗收案例；12個符合、4個失敗，所有案例權重相同僅供教學統計。 12/16×100=75%；修正其中兩個後14/16×100=87.5%，高風險失敗仍不可被平均掩蓋。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Evidence coverage is complete, fresh evidence divided by a fixed requirement count; maturity categories are ordinal, not numbers to average into a security score. A teaching checklist has 25 requirements; 17 have a configuration snapshot, owner and recent test, while 8 lack evidence. Coverage is 17/25×100=68%; completing 4 more yields 21/25×100=84%, with 4 unverified.","Assurance is a vector of separate requirements; local conformance counts only the chosen acceptance fixtures and is not a NIST certification score. A custom service profile has 16 acceptance fixtures: 12 pass and 4 fail, equally weighted only for teaching statistics. 12/16×100=75%; repairing two yields 14/16×100=87.5%, but averages cannot hide a high-impact failure.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-012","referenceUrls":["https://www.rfc-editor.org/rfc/rfc8446.html"],"title":"TLS 1.3：握手轉錄與金鑰分離","titleEn":"TLS 1.3: handshake transcripts and key separation","why":"用兩課的可觀察驗收條件比較模型邊界：覆蓋率可從原始清單重算，沒有平均序位等級；每個未驗證項目都有負責人與截止日。 交付25項證據矩陣、五支柱差距說明與下一輪驗證排程。","whyEn":"Compare model boundaries using observable acceptance criteria: Coverage can be recomputed from raw rows without averaging ordinal levels; every unverified item has an owner and deadline. Deliver the 25-item evidence matrix, pillar-by-pillar gap analysis and next validation schedule.","difference":"以虛構ClientHello、ServerHello、Certificate、CertificateVerify及Finished畫時序；區分握手金鑰與應用金鑰，標明transcript涵蓋訊息。","differenceEn":"Draw a fictional ClientHello, ServerHello, Certificate, CertificateVerify and Finished sequence; distinguish handshake/application keys and transcript coverage.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["證據覆蓋率=有完整且未過期證據的需求數/固定需求總數；成熟度等級是序位，不能直接平均成安全分數。 教學清單25項；17項有設定快照、負責人與最近一次測試，8項缺證據。 覆蓋17/25×100=68%；補齊4項後21/25×100=84%，仍有4項未驗證。","本題簡化握手延遲=一個網路RTT+兩端合計計算時間；不含DNS、TCP建連與應用回應，不能當網頁總延遲。 合成鏈路RTT40毫秒，端點計算合計8毫秒；無HelloRetryRequest或封包遺失。 40+8=48毫秒；RTT改80毫秒、計算不變時為88毫秒。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Evidence coverage is complete, fresh evidence divided by a fixed requirement count; maturity categories are ordinal, not numbers to average into a security score. A teaching checklist has 25 requirements; 17 have a configuration snapshot, owner and recent test, while 8 lack evidence. Coverage is 17/25×100=68%; completing 4 more yields 21/25×100=84%, with 4 unverified.","Simplified handshake latency is one network RTT plus combined endpoint computation; it excludes DNS, TCP setup and application response and is not total page latency. A synthetic link has RTT 40 ms and combined computation 8 ms, with no HelloRetryRequest or loss. 40+8=48 ms; RTT 80 ms with unchanged computation gives 88 ms.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-8005cb990aa13586","url":"https://csrc.nist.gov/pubs/sp/800/63/4/final","title":"NIST SP 800-63-4: Digital Identity Guidelines","titleEn":"NIST SP 800-63-4: Digital Identity Guidelines","publisher":"NIST","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-e28608fb71a795c2","url":"https://www.rfc-editor.org/rfc/rfc8446.html","title":"RFC 8446: TLS 1.3","titleEn":"RFC 8446: TLS 1.3","publisher":"IETF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
